<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('settings.manage');$pdo=Database::connection();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$values=['platform_name'=>trim($_POST['platform_name']??''),'whatsapp_number'=>preg_replace('/\D+/','',$_POST['whatsapp_number']??''),'default_currency'=>in_array($_POST['default_currency']??'SAR',['SAR','YER'],true)?$_POST['default_currency']:'SAR','support_email'=>trim($_POST['support_email']??'')];try{foreach($values as $k=>$v){$q=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$k,$v]);}admin_log($pdo,$user,'settings.updated','settings',0,'تحديث إعدادات المنصة');redirect('/admin/settings.php?saved=1');}catch(Throwable){$error='تعذر حفظ الإعدادات.';}}$vals=[];foreach(['platform_name'=>'أصل المتصدر','whatsapp_number'=>'967733148606','default_currency'=>'SAR','support_email'=>''] as $k=>$d)$vals[$k]=setting($k,$d);admin_page_start('إعدادات المنصة',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ الإعدادات في قاعدة البيانات.</p>';echo '<section class="panel"><p class="muted">هذه القيم تحفظ إعدادات التشغيل العامة. بيانات اتصال قاعدة البيانات تبقى في ملف البيئة ولا تعرض هنا.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><label>اسم المنصة<input name="platform_name" value="'.e($vals['platform_name']).'" required></label><label>واتساب الاستقبال<input name="whatsapp_number" value="'.e($vals['whatsapp_number']).'"></label><label>العملة الافتراضية<select name="default_currency"><option value="SAR" '.($vals['default_currency']==='SAR'?'selected':'').'>ريال سعودي</option><option value="YER" '.($vals['default_currency']==='YER'?'selected':'').'>ريال يمني</option></select></label><label>بريد الدعم<input type="email" name="support_email" value="'.e($vals['support_email']).'"></label><button class="btn btn-primary">حفظ الإعدادات</button></form></section>';admin_page_end();
